from aperture import read_csv, parameters, write_json, write_csv
from decimal import Decimal, InvalidOperation, getcontext
getcontext().prec = 40
cfg = parameters()
category_column = cfg.get("category_column", "category")
amount_column = cfg.get("amount_column", "amount")
decimal_separator = cfg.get("decimal_separator", ".")
thousands_separator = cfg.get("thousands_separator", "")
missing_category = cfg.get("missing_category", "uncategorized")
if decimal_separator not in [".", ","] or thousands_separator not in ["", ",", ".", " "] or decimal_separator == thousands_separator:
    raise ValueError("Choose distinct decimal and thousands separators")
if missing_category not in ["uncategorized", "reject"]:
    raise ValueError("Choose uncategorized or reject for missing categories")
groups = {}
valid = 0
invalid = 0
missing_groups = 0
reasons = {}
examples = []
for row_number, row in enumerate(read_csv(cfg["input_name"], delimiter=cfg.get("delimiter", ","), required_columns=[category_column, amount_column]), 2):
    reason = None
    category = (row.get(category_column) or "").strip()
    raw = (row.get(amount_column) or "").strip()
    if None in row:
        reason = "extra_fields"
    elif not raw:
        reason = "missing_amount"
    elif not category and missing_category == "reject":
        reason = "missing_category"
    elif len(category) > 200:
        reason = "category_too_long"
    else:
        try:
            if thousands_separator:
                parts = raw.lstrip("+-").split(decimal_separator)
                integer_groups = parts[0].split(thousands_separator)
                if len(integer_groups) > 1 and (not 1 <= len(integer_groups[0]) <= 3 or any(len(part) != 3 or not part.isdigit() for part in integer_groups[1:])):
                    raise ValueError("Invalid thousands grouping")
                raw = raw.replace(thousands_separator, "")
            if "_" in raw or (decimal_separator != "." and "." in raw):
                raise ValueError("Amount does not match the chosen numeric separators")
            amount = Decimal(raw.replace(decimal_separator, "."))
            if not amount.is_finite():
                reason = "non_finite_amount"
            elif abs(amount) > Decimal("1000000000000000") or amount.as_tuple().exponent < -6:
                reason = "amount_out_of_range"
        except (InvalidOperation, ValueError):
            reason = "invalid_amount"
    if reason:
        invalid += 1
        reasons[reason] = reasons.get(reason, 0) + 1
        if len(examples) < 20:
            examples.append({"file": cfg["input_name"], "record": row_number - 1, "reason": reason})
        continue
    if not category:
        category = "uncategorized"
        missing_groups += 1
    if category not in groups:
        if len(groups) >= 10000:
            raise ValueError("More than 10000 groups; split this workload or use a coarser grouping")
        groups[category] = {"rows": 0, "sum": Decimal(0), "min": amount, "max": amount}
    group = groups[category]
    group["rows"] += 1
    group["sum"] += amount
    group["min"] = min(group["min"], amount)
    group["max"] = max(group["max"], amount)
    valid += 1
output_groups = {key: {"rows": group["rows"], "total": float(group["sum"]), "total_decimal": str(group["sum"]),
    "minimum": float(group["min"]), "maximum": float(group["max"])} for key, group in sorted(groups.items())}
quality = {"invalid_reasons": reasons, "missing_category_rows": missing_groups, "examples": examples,
    "duplicate_check": "not_performed", "numeric_policy": "decimal; up to 6 fractional digits; absolute value <= 1e15"}
report = {"version": 2, "valid_rows": valid, "invalid_rows": invalid, "groups": output_groups, "quality": quality,
    "mapping": {"category_column": category_column, "amount_column": amount_column, "delimiter": cfg.get("delimiter", ","),
        "decimal_separator": decimal_separator, "thousands_separator": thousands_separator, "missing_category": missing_category},
    "files": [cfg["input_name"]]}
write_json(cfg.get("output_name", "report.json"), report)
if cfg.get("csv_output", True):
    rows = [{"category": ("'" + key if key.startswith(("=", "+", "-", "@", "\t", "\r")) else key),
        "rows": group["rows"], "total": group["total_decimal"], "average": format(round(Decimal(group["total_decimal"]) / group["rows"], 4).normalize(), "f"),
        "minimum": group["minimum"], "maximum": group["maximum"]} for key, group in output_groups.items()]
    write_csv("categories.csv", rows, ["category", "rows", "total", "average", "minimum", "maximum"])
print("Processed", valid + invalid, "records;", invalid, "excluded; inspect report quality for reasons")
